public protocol EngineProtocol: AnyObject, Sendable {
    
    /**
     * Adds the feed behind `input`, stores what it lists now (without
     * announcing any of it) and puts it into the given collections.
     */
    func addSource(input: String, notify: Bool, collectionIds: [String]) throws  -> FeedSource
    
    func article(key: String) throws  -> ArticleDetail?
    
    func articles(query: ArticleQuery) throws  -> [Article]
    
    /**
     * Stops a refresh after the feeds already on their way.
     * Also stops the next one if none is running yet.
     */
    func cancel() 
    
    func collections() throws  -> [FeedCollection]
    
    func counts() throws  -> Counts
    
    func deleteCollection(id: String) throws 
    
    func deleteSource(id: String) throws 
    
    /**
     * Every source, those in a hand-picked collection inside its folder.
     */
    func exportOpml() throws  -> String
    
    /**
     * Adds every feed of an OPML file not followed yet, folders as
     * collections. Says how many sources came in; nothing is fetched.
     */
    func importOpml(data: Data) throws  -> UInt32
    
    func markAllRead(scope: Scope) throws 
    
    func orderCollections(ids: [String]) throws 
    
    /**
     * Finds the feed behind an address (a feed, or a page that links one)
     * and shows what it holds, without adding it.
     */
    func preview(input: String) throws  -> FeedPreview
    
    /**
     * Forgets read, unstarred articles older than `keep_days`; says how many.
     */
    func prune(keepDays: UInt32) throws  -> UInt32
    
    /**
     * Fetches every source, or the one given, and says what is new and
     * which of it to announce. Failures land in the report and on the
     * source, never as an error.
     */
    func refresh(sourceId: String?)  -> RefreshReport
    
    /**
     * Creates the collection when its id is empty, otherwise changes it.
     */
    func saveCollection(collection: FeedCollection) throws  -> FeedCollection
    
    func setRead(keys: [String], read: Bool) throws 
    
    func setStarred(key: String, starred: Bool) throws 
    
    func sources() throws  -> [FeedSource]
    
    /**
     * Renames a source (empty: back to the feed's own title) and switches
     * its notifications.
     */
    func updateSource(id: String, title: String, notify: Bool) throws 
    
    /**
     * Withdraws the offered code: nobody can join with it any more.
     */
    func cancelPairing() throws 
    
    func connectLock(signIn: LockSignIn) throws  -> LockResult
    
    /**
     * Makes a UwUSync account from a server's setup code; the recovery code
     * comes back, to be written down.
     */
    func createSyncAccount(setupCode: String, password: String) throws  -> String
    
    /**
     * Stops syncing; everything here stays.
     */
    func disconnectSync() throws 
    
    /**
     * Joins a UwUSync account another device shows a code for: the pasted
     * form, or the spoken one with the server's address.
     */
    func joinSync(code: String, serverUrl: String?, fingerprint: String?, password: String, flavor: AccountFlavor) throws 
    
    /**
     * Opens a pairing for another device; then [`Self::wait_for_device`].
     */
    func offerPairing() throws  -> PairingCode
    
    func sendLockEmailCode(serverUrl: String, email: String, password: String) throws 
    
    /**
     * One pass up and down. Not connected is an error; the app checks
     * [`Self::sync_status`] first.
     */
    func syncNow() throws  -> SyncSummary
    
    func syncStatus() throws  -> SyncStatus
    
    /**
     * The master password, when this device lost its vault key.
     */
    func unlockSync(password: String) throws 
    
    /**
     * Waits for the device the last offer was for; its name comes back.
     */
    func waitForDevice(timeoutSecs: UInt32) throws  -> String
    
}
