@_documentation(visibility: private)
#endif
public func FfiConverterTypeSecretStore_lower(_ value: SecretStore) -> UInt64 {
    return FfiConverterTypeSecretStore.lower(value)
}




public struct Article: Equatable, Hashable {
    public var key: String
    public var sourceId: String
    public var sourceTitle: String
    public var title: String
    public var summary: String
    public var link: String?
    public var author: String?
    public var imageUrl: String?
    public var publishedAt: Int64?
    /**
     * What lists sort by: the publication time, or when it was fetched.
     */
    public var sortAt: Int64
    public var read: Bool
    public var starred: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(key: String, sourceId: String, sourceTitle: String, title: String, summary: String, link: String?, author: String?, imageUrl: String?, publishedAt: Int64?, 
        /**
         * What lists sort by: the publication time, or when it was fetched.
         */sortAt: Int64, read: Bool, starred: Bool) {
        self.key = key
        self.sourceId = sourceId
        self.sourceTitle = sourceTitle
        self.title = title
        self.summary = summary
        self.link = link
        self.author = author
        self.imageUrl = imageUrl
        self.publishedAt = publishedAt
        self.sortAt = sortAt
        self.read = read
        self.starred = starred
    }

    

    
}

