    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> [TwoFactorOption] {
        let len: Int32 = try readInt(&buf)
        var seq = [TwoFactorOption]()
        seq.reserveCapacity(Int(len))
        for _ in 0 ..< len {
            seq.append(try FfiConverterTypeTwoFactorOption.read(from: &buf))
        }
        return seq
    }
}

